function renderHome(){if(!state.onboarded)return;state=applyElapsedTime(state,vNow());save();const s=status(),r=resting(s),pose=transientPose||r.pose,location=transientLocation||r.location;updateArts();e.app.dataset.phase=s.phase;e.room.dataset.roomPhase=s.phase;e.room.dataset.roomAction=pose;e.mainPet.dataset.pose=pose;e.mainPet.dataset.location=location;e.petNameTitle.textContent=state.petName;e.clock.textContent=new Date(s.now).toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'});e.clock.dateTime=new Date(s.now).toISOString();e.phaseLabel.textContent=phaseLabel(s.phase);e.growthChip.textContent=`${s.growth.label}・${s.growth.day}日目`;e.hungerText.textContent=hungerLabel(state.fullness,s.meal.overdue);e.activityText.textContent=activityLabel(pose,s.sleep,s.meal.overdue);e.daysText.textContent=`${getDaysTogether(state,s.now)}日目`;e.outingLabel.textContent=state.kind==='dog'?'散歩':'探索';if(!busy)notice(defaultMessage(s),s.sleep?'sleep':s.meal.overdue?'hunger':'calm');e.debugClock.textContent=new Date(s.now).toLocaleString('ja-JP',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});e.debugGrowth.textContent=`${s.growth.label} ${s.growth.day}日目`;e.debugSave.textContent=saveHealthy?'正常':'保存不可';e.settingsBreakfast.value=state.routine.breakfast;e.settingsDinner.value=state.routine.dinner;e.settingsWake.value=state.routine.wake;e.settingsBed.value=state.routine.bedtime;renderMemories()}
