function reaction(kind,z,preview=false){const name=preview?'この子':state.petName;if(kind==='cat')return z==='head'?`${name}は目を細め、額を指先へ少し近づけました。`:z==='tail'?`${name}はしっぽを動かし、触られた場所を確かめるように振り返りました。`:`${name}は呼吸をゆるめ、背中を手の動きへ預けました。`;return z==='head'?`${name}は顔を上げ、もっと触れてほしそうに見ています。`:z==='tail'?`${name}のしっぽが大きく動き、身体ごとこちらへ向きました。`:`${name}は身体を寄せ、手の動きに合わせて姿勢を変えました。`}
