async function feedSequence(food){if(busy)return;closeSheet();stopToy(false);busy=true;e.foodBowl.dataset.food=food;e.foodBowl.classList.remove('food-draining');setPet('notice',e.mainPet.dataset.location||'center',`${state.petName}が食事の香りに気づきました。`);await wait(650);setPet('walk','bowl',`${state.petName}は食器へ向かっています。`);await wait(1250);setPet('sniff','bowl',`${state.petName}はすぐに食べず、何度か匂いを確かめています。`);await wait(900);e.foodBowl.classList.add('eating','food-draining');setPet('eat','bowl',`${state.petName}は落ち着いて食べ始めました。`);await wait(food==='treat'?1700:2900);state=feedPet(state,food,vNow());save();e.foodBowl.classList.remove('eating');setPet('satisfied','bowl',food==='treat'?`${state.petName}は食べ終え、まだ少し期待するようにこちらを見ました。`:`${state.petName}は口元をぺろりとし、満足したように顔を上げました。`);haptic([12,28,12]);await wait(1050);e.foodBowl.dataset.food='empty';e.foodBowl.classList.remove('food-draining');const s=status();if(s.sleep){setPet('walk','bed',`${state.petName}は食事を終え、寝床へ戻ります。`);await wait(1150);setPet('sleep','bed',`${state.petName}は身体を丸め、再び眠り始めました。`,'sleep')}else{setPet('walk','center',`${state.petName}は食器を離れ、いつもの場所へ戻ります。`);await wait(1150)}busy=false;clearPet();toast('食事の一連の動作を記録しました');scheduleIdle()}
function startToy(){if(busy)return;closeSheet();if(toyMode){stopToy(true);return}busy=true;e.toy.hidden=false;e.toy.classList.remove('hidden');e.toy.dataset.toyKind=state.kind;e.toy.style.setProperty('--toy-x','0px');e.toy.style.setProperty('--toy-y','0px');setPet('notice','center',state.kind==='dog'?`${state.petName}はボールから目を離しません。指で動かしてみてください。`:`${state.petName}はおもちゃの先を見つめています。指で動かしてみてください。`);toyMode={distance:0,completed:false};toast('おもちゃを指で動かすと追いかけます',3200)}
