function bindToy(){let p=null;e.toy.addEventListener('pointerdown',ev=>{if(!toyMode)return;p={id:ev.pointerId,lx:ev.clientX,ly:ev.clientY};e.toy.setPointerCapture?.(ev.pointerId)});e.toy.addEventListener('pointermove',ev=>{if(!toyMode||!p||p.id!==ev.pointerId)return;const r=e.room.getBoundingClientRect(),x=clamp(ev.clientX-r.left-r.width/2,-r.width*.36,r.width*.36),y=clamp(ev.clientY-r.top-r.height*.42,-r.height*.22,r.height*.29);e.toy.style.setProperty('--toy-x',`${x}px`);e.toy.style.setProperty('--toy-y',`${y}px`);toyMode.distance+=Math.hypot(ev.clientX-p.lx,ev.clientY-p.ly);p.lx=ev.clientX;p.ly=ev.clientY;if(toyMode.distance>210)completeToy()});e.toy.addEventListener('pointerup',ev=>{if(!p||p.id!==ev.pointerId)return;p=null;if(toyMode?.distance>95)completeToy()});e.toy.addEventListener('pointercancel',()=>p=null);e.toy.addEventListener('keydown',ev=>{if(toyMode&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(ev.key)){ev.preventDefault();toyMode.distance+=55;if(toyMode.distance>160)completeToy()}})}
async function outing(){if(busy)return;stopToy(false);busy=true;if(state.kind==='cat'){setPet('notice','center',`${state.petName}は窓の外の小さな音に耳を向けました。`);await wait(700);setPet('walk','window',`${state.petName}は自分から窓辺へ移動しています。`);await wait(1250);setPet('attentive','window',`${state.petName}は外を眺め、鳥の動きを静かに追っています。`);await wait(2200);state=addMemory(state,'窓辺で見つけたもの',`${state.petName}は窓の外を長く眺め、動く影へ何度も耳を向けました。`,vNow(),'explore')}else{setPet('attentive','center',`${state.petName}は外へ出る気配に気づき、玄関の方を見ました。`);await wait(700);setPet('walk','door',`${state.petName}は玄関へ向かい、短い散歩を待っています。`);await wait(1250);setPet('play','door',`${state.petName}は外の匂いを確かめ、戻るとしっぽを大きく振りました。`);await wait(2100);state=addMemory(state,'短い散歩',`${state.petName}は近所の匂いを確かめながら歩き、帰ると水を飲んで休みました。`,vNow(),'walk')}save();setPet('walk','center',`${state.petName}はいつもの場所へ戻ります。`);await wait(1150);busy=false;clearPet();toast(state.kind==='cat'?'窓辺での出来事を記録しました':'散歩の記録を残しました');scheduleIdle()}
