async function runIdle(){if(busy||document.hidden||status().sleep){scheduleIdle();return}busy=true;const opts=state.kind==='cat'?[['groom','center',`${state.petName}は前足を舐め、顔のまわりをゆっくり整えています。`],['stretch','center',`${state.petName}は前足を伸ばし、身体を大きく伸ばしました。`],['attentive','center',`${state.petName}は部屋の小さな音へ耳だけを向けました。`]]:[['stretch','center',`${state.petName}は立ち上がる前に、前足を伸ばして身体をほぐしました。`],['attentive','center',`${state.petName}はあなたの方を見て、しっぽを一度だけ動かしました。`],['groom','center',`${state.petName}は前足の匂いを確かめ、短く毛づくろいしました。`]],o=opts[Math.floor(Math.random()*opts.length)];setPet(o[0],o[1],o[2]);await wait(o[0]==='stretch'?1500:1800);busy=false;clearPet();scheduleIdle()}
function notification(){if(!('Notification'in window)){toast('このブラウザーでは通知見本を表示できません');return}const show=()=>new Notification('Tail Room',{body:`${state.petName}が空の食器を確認しています。ごはんの時間を少し過ぎたようです。`});if(Notification.permission==='granted')show();else if(Notification.permission==='default')Notification.requestPermission().then(p=>p==='granted'?show():toast('通知は許可されませんでした'));else toast('通知は端末設定でオフになっています')}
function bind(){ $$('.species-option').forEach(b=>b.addEventListener('click',()=>{selectedKind=b.dataset.kind==='dog'?'dog':'cat';previewTouched=false;e.toNameStep.disabled=true;e.touchPrompt.classList.remove('done');syncSpecies();e.previewPet.dataset.pose='attentive';setTimeout(()=>e.previewPet.dataset.pose='idle',700)}));e.toNameStep.addEventListener('click',()=>setStep(1));e.toRoutineStep.addEventListener('click',()=>{if(!e.petNameInput.value.trim()){e.petNameInput.focus();toast('この子を呼ぶ名前を入力してください');return}setStep(2);updateRoutinePreview()});$$('[data-back-step]').forEach(b=>b.addEventListener('click',()=>setStep(b.dataset.backStep)));e.petNameInput.addEventListener('input',()=>{const name=e.petNameInput.value.trim();e.nameReaction.textContent=name?`${name}と呼ぶと、こちらへ少し顔を向けました。`:'名前を呼ばれるのを待っています。';e.namePet.dataset.pose=name?'attentive':'idle';updateRoutinePreview()});[e.breakfastInput,e.dinnerInput,e.wakeInput,e.bedtimeInput].forEach(x=>x.addEventListener('change',updateRoutinePreview));e.startLife.addEventListener('click',()=>{state=beginLife(state,{kind:selectedKind,petName:e.petNameInput.value,routine:{breakfast:e.breakfastInput.value,dinner:e.dinnerInput.value,wake:e.wakeInput.value,bedtime:e.bedtimeInput.value}},Date.now());save();showHome();toast(`${state.petName}との暮らしが始まりました`)});$$('.care-button').forEach(b=>b.addEventListener('click',()=>{const a=b.dataset.action;if(a==='feed')openSheet(e.foodSheet);if(a==='play')startToy();if(a==='outing')outing();if(a==='rest')rest()}));$$('[data-food-choice]').forEach(b=>b.addEventListener('click',()=>feedSequence(b.dataset.foodChoice)));e.openDeveloper.addEventListener('click',()=>openSheet(e.developerSheet));e.openMemories.addEventListener('click',()=>{renderMemories();openSheet(e.memoriesSheet)});e.modalBackdrop.addEventListener('click',closeSheet);$$('[data-close-sheet]').forEach(b=>b.addEventListener('click',closeSheet));$$('[data-time-jump]').forEach(b=>b.addEventListener('click',()=>{state=advanceVirtualTime(state,Number(b.dataset.timeJump));state=applyElapsedTime(state,vNow());save();renderHome();toast('制作者用の仮想時間を進めました')}));$$('[data-debug-action]').forEach(b=>b.addEventListener('click',()=>{const a=b.dataset.debugAction;if(a==='hunger'){state=setForcedHunger(state,!state.debug.forcedHunger);toast(state.debug.forcedHunger?'空腹状態を再現しました':'空腹再現を解除しました')}if(a==='sleep'){state=setForcedSleep(state,!state.debug.forcedSleep);toast(state.debug.forcedSleep?'就寝状態を再現しました':'就寝再現を解除しました')}if(a==='notification')notification();if(a==='reset-time'){state=resetVirtualTime(state);toast('実際の時刻へ戻しました')}save();renderHome()}));e.saveRoutine.addEventListener('click',()=>{state=updateRoutine(state,{breakfast:e.settingsBreakfast.value,dinner:e.settingsDinner.value,wake:e.settingsWake.value,bedtime:e.settingsBed.value});save();renderHome();toast('生活時間を保存しました')});e.resetApp.addEventListener('click',()=>{if(confirm('確認データを削除して、最初の出会いからやり直しますか？')){localStorage.removeItem(STORAGE_KEY);location.reload()}});document.addEventListener('visibilitychange',()=>{if(document.hidden){state.lastSeenAt=vNow();save();clearTimeout(idleTimer)}else{state=applyElapsedTime(state,vNow());save();renderHome();scheduleIdle()}});window.addEventListener('pagehide',()=>{state.lastSeenAt=vNow();save()});window.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeSheet()})}
function init(){e.buildBadge.textContent=`PREVIEW 0.${APP_VERSION}`;e.breakfastInput.value=state.routine?.breakfast||DEFAULT_ROUTINE.breakfast;e.dinnerInput.value=state.routine?.dinner||DEFAULT_ROUTINE.dinner;e.wakeInput.value=state.routine?.wake||DEFAULT_ROUTINE.wake;e.bedtimeInput.value=state.routine?.bedtime||DEFAULT_ROUTINE.bedtime;selectedKind=state.kind||'cat';syncSpecies();updateArts();bindPet(e.previewPet,()=>selectedKind,true);bindPet(e.mainPet,()=>state.kind,false);bindToy();bind();if(state.onboarded)showHome();else showOnboarding();setInterval(()=>{if(state.onboarded&&!busy)renderHome()},30_000);window.__TAIL_ROOM_READY__=true}
clearLegacy().finally(init)
